import Foundation

protocol ItemRepository {
    func fetchAll() -> [Item]
    /// Assigns a fresh autogenerated `code` and saves the item, returning
    /// the saved copy (with `code` filled in).
    @discardableResult
    func create(_ item: Item) throws -> Item
    /// Saves an existing item, keeping its current `code`.
    func update(_ item: Item) throws
    func delete(id: UUID) throws
}
